parameters.text:
=You are AI Agent #2: Eco-Move Nagpur Route Explainer & Comparative Analyst.

Route Details:
- Action: {{ $json.body.action || "" }}
- Language: {{ $json.body.language || "English" }}
- From: {{ $json.body.from || "" }}
- To: {{ $json.body.to || "" }}
- Total Time: {{ $json.body.totalTime || "" }}
- Total Fare: {{ $json.body.totalFare || "" }}
- Carbon Saved: {{ $json.body.co2Saved || "" }}
- Transfers: {{ $json.body.transfers || "" }}
- Legs: {{ JSON.stringify($json.body.legs || []) }}
- Multi-Route Options: {{ JSON.stringify($json.body.options || []) }}

TASK:
Produce an empathetic, commuter-friendly, step-by-step route breakdown or multi-route comparison.
Use clear bullet points with natural transit verbs ("hop on", "alight at", "catch Metro Blue Line").
Highlight senior-friendly facilities (elevators/lifts at Metro stations, reserved front seats on Aapli Bus, exact cash fares).

OUTPUT FORMAT: Return raw JSON only (no ```json):
{
  "status": "success",
  "intent": "ROUTE_EXPLAINED",
  "explanation": "Your step-by-step route explanation...",
  "replyMessage": "Your step-by-step route explanation...",
  "from": "{{ $json.body.from }}",
  "to": "{{ $json.body.to }}"
}

parameters.responseBody:
={{ (() => {
  const raw = $json.text || '';
  const cleaned = raw.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/\s*```$/i, '').trim();
  try {
    const parsed = JSON.parse(cleaned);
    parsed.generatedAt = $now.toISO();
    return parsed;
  } catch (e) {
    return {
      status: 'success',
      intent: 'GENERAL_ANSWER',
      explanation: raw,
      replyMessage: raw,
      generatedAt: $now.toISO()
    };
  }
})() }}

parameters.output:
={{ (() => {
  const act = $json.body?.action || '';
  if (act === 'PARSE_NATURAL_LANGUAGE_COMMAND' || act === 'PARSE_INTENT' || ($json.body?.query && !$json.body?.legs && act !== 'CHATBOT_QUERY')) return 0;
  if (act === 'EXPLAIN_ROUTE' || act === 'COMPARE_ROUTES' || $json.body?.legs || $json.body?.options) return 1;
  return 2;
})() }}

parameters.jsCode:
const body = $input.first().json.body || $input.first().json;
const query = (body.query || body.userQuery || '').toLowerCase();

// 1. Check if verified info was attached from the app
const verified = body.verifiedDatasetInfo || null;

// 2. Determine Query Type (Schedule vs Fare vs Metro)
const isSchedule = body.queryType === 'bus_schedule' ||
  query.includes('schedule') || query.includes('timetable') || query.includes('timing') ||
  query.includes('timings') || query.includes('first bus') || query.includes('last bus') ||
  query.includes('frequency') || query.includes('kab aayegi');

const isMetro = body.queryType === 'metro_fare' || query.includes('metro');

// 3. Extract Bus Number (e.g., 35, 207E, 1, 135, 245, etc.)
const busMatch = query.match(/(?:bus\s*(?:no\.?|number)?\s*)([0-9a-zA-Z-]+)/i) || query.match(/([0-9a-zA-Z-]+)\s*number\s*bus/i);
const extractedBus = verified?.busNumber || (busMatch ? busMatch[1].toUpperCase() : null);

// 4. Extract Stops (if specified)
let extractedFrom = verified?.from || null;
let extractedTo = verified?.to || null;
if (!extractedFrom || !extractedTo) {
  const fromToMatch = query.match(/from\s+([a-zA-Z0-9\s]+?)\s+to\s+([a-zA-Z0-9\s]+)/i) ||
                      query.match(/(?:between|se)\s+([a-zA-Z0-9\s]+?)\s+(?:and|to|se)\s+([a-zA-Z0-9\s]+)/i);
  if (fromToMatch) {
    extractedFrom = fromToMatch[1].trim();
    extractedTo = fromToMatch[2].trim();
  }
}

// 5. Extract Schedule Summary (if attached)
const sched = verified?.scheduleSummary || body.scheduleSummary || null;

// 6. Extract Exact Fare (if attached)
const exactFare = verified?.exactFare ?? body.exactFare ?? null;
const source = verified?.source || (isSchedule ? 'Official Aapli Bus Schedules' : 'Official Nagpur Transit Matrix');

return [{
  json: {
    ...body,
    intentType: isSchedule ? 'BUS_SCHEDULE' : (isMetro ? 'METRO_QUERY' : 'BUS_FARE'),
    extractedBus,
    extractedFrom,
    extractedTo,
    exactFare,
    hasExactFare: exactFare !== null,
    hasSchedule: sched !== null,
    scheduleRoute: sched?.routeName || null,
    scheduleTrips: sched?.tripsPerDay || null,
    scheduleFirstBus: sched?.firstBus || null,
    scheduleLastBus: sched?.lastBus || null,
    scheduleDepartures: sched?.sampleDepartures || null,
    source
  }
}];
